-- 304: Seed 9 more lead-magnet blog posts (MMD_Blog), one per WSQ course.
--
-- Same pattern as 303's sample post: each INSERT is idempotent (WHERE NOT
-- EXISTS on url_key), the `content` HTML value is intentionally ONE line
-- (apply.php splits on ";" at end-of-line, so no content line may end in ";"),
-- and single quotes inside the body are SQL-doubled (''). Every post is a lead
-- magnet: it links to the course page and pushes the WSQ funding /
-- SkillsFuture Credit hook. `source_sku` is set so the Monday autoblog cron
-- treats these courses as already blogged and picks fresh ones.
--
-- Tags reuse the core Magento `tag` table via mmd_blog_post_tag.

-- =====================================================================
-- 1) Urban Farming with Hydroponics — TGS-2025053916
-- =====================================================================
INSERT INTO `mmd_blog_post` (`title`, `url_key`, `excerpt`, `content`, `author`, `status`, `published_at`, `related_skus`, `source_sku`, `meta_title`, `meta_description`, `meta_keywords`, `created_at`, `updated_at`) SELECT 'Urban Farming with Hydroponics: Grow Fresh Food Without Soil', 'urban-farming-with-hydroponics-guide', 'Hydroponics lets you grow leafy greens and herbs faster than soil, in a spare corner of your home or office. Here is how it works and how to master it with up to 70% WSQ funding and SkillsFuture Credit.', '<h2>Why hydroponics is booming in land-scarce Singapore</h2><p>Singapore imports more than 90% of its food, and the national "30 by 30" goal aims to produce 30% of our nutritional needs locally by 2030. Hydroponics — growing plants in nutrient-rich water instead of soil — is at the heart of that push. It uses up to 90% less water than traditional farming, needs no arable land, and can run indoors under LED lights all year round.</p><h2>What exactly is hydroponics?</h2><p>Hydroponics delivers water, oxygen and dissolved nutrients directly to plant roots, so plants grow faster and cleaner without soil. The common beginner-friendly systems are:</p><ul><li><strong>Deep Water Culture (DWC)</strong> — roots sit in oxygenated nutrient water; simplest to start with</li><li><strong>Nutrient Film Technique (NFT)</strong> — a thin film of nutrient solution flows past the roots in channels</li><li><strong>Kratky method</strong> — a passive, no-pump setup ideal for herbs and small greens</li><li><strong>Ebb and flow</strong> — periodically floods and drains the grow bed</li></ul><h2>What you can grow</h2><table><tr><th>Crop</th><th>Time to harvest</th></tr><tr><td>Lettuce, bok choy, kai lan</td><td>3 to 5 weeks</td></tr><tr><td>Basil, mint, coriander</td><td>3 to 6 weeks</td></tr><tr><td>Kale, spinach, chye sim</td><td>4 to 6 weeks</td></tr><tr><td>Cherry tomatoes, chilli</td><td>8 to 12 weeks</td></tr></table><p>In our hands-on class you build and run a working hydroponic system, learn to mix nutrients, balance pH and EC, and troubleshoot common problems. The <a href="{{store direct_url=''wsq-basic-urban-farming-with-hydroponics.html''}}">WSQ Basic Urban Farming with Hydroponics course</a> takes you from zero to your first harvest.</p><h2>Who should learn this?</h2><ul><li>Home gardeners who want fresh, pesticide-free greens year-round</li><li>Aspiring urban farmers and agripreneurs exploring a new business</li><li>F&amp;B owners wanting to grow their own herbs and microgreens</li><li>Educators, community-garden leaders and sustainability advocates</li></ul><h2>Fund your learning: WSQ funding + SkillsFuture Credit</h2><p>This is a <strong>WSQ-accredited course</strong>, so eligible Singaporeans and PRs enjoy <strong>up to 70% WSQ course-fee funding</strong>, and Singaporeans can <strong>use SkillsFuture Credit</strong> to offset the balance — often bringing the out-of-pocket cost close to zero. Company-sponsored staff enjoy the same subsidies plus absentee payroll support. <a href="{{store direct_url=''wsq-basic-urban-farming-with-hydroponics.html''}}">Check your funding eligibility and class dates here</a>.</p><h2>FAQ</h2><h3>Do I need a garden or balcony?</h3><p>No. A hydroponic rack fits in a kitchen corner, spare room or office pantry under LED grow lights. We cover compact indoor setups in class.</p><h3>Can I claim SkillsFuture Credit for this course?</h3><p>Yes. As a WSQ course it is SkillsFuture-eligible — apply the WSQ subsidy first, then use your SkillsFuture Credit for the nett fee. Our team handles the paperwork.</p><h3>Is hydroponics hard to maintain?</h3><p>Once your system is dialled in, it takes only minutes a day. The skill is in the setup and nutrient balance, which is exactly what the course drills.</p><h2>What to do next</h2><ol><li>Decide what you want to grow first — salad greens and herbs are the easiest wins</li><li>Reserve a seat in the <a href="{{store direct_url=''wsq-basic-urban-farming-with-hydroponics.html''}}"><strong>WSQ Basic Urban Farming with Hydroponics</strong></a> class — funded places fill quickly</li><li>Leave with a working system design and the confidence to grow your own food</li></ol>', 'Tertiary Infotech Academy', 1, '2026-06-16', 'TGS-2025053916', 'TGS-2025053916', 'Urban Farming with Hydroponics Course Singapore | WSQ Funded', 'Learn how hydroponics works and grow fresh greens without soil. Hands-on WSQ course in Singapore with up to 70% funding and SkillsFuture Credit.', 'hydroponics, urban farming, wsq course, skillsfuture, grow without soil, indoor farming singapore', NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `mmd_blog_post` WHERE `url_key` = 'urban-farming-with-hydroponics-guide');

-- =====================================================================
-- 2) Python Fundamentals — TGS-2019503161
-- =====================================================================
INSERT INTO `mmd_blog_post` (`title`, `url_key`, `excerpt`, `content`, `author`, `status`, `published_at`, `related_skus`, `source_sku`, `meta_title`, `meta_description`, `meta_keywords`, `created_at`, `updated_at`) SELECT 'Python for Beginners: The Fastest Path to Your First Program', 'python-fundamentals-for-beginners', 'Python is the most in-demand programming language for data, AI and automation, and it is beginner-friendly. Here is what you can build and how to learn it with up to 70% WSQ funding and SkillsFuture Credit.', '<h2>Why Python is the best first language to learn</h2><p>Python powers data science, artificial intelligence, web backends, automation and scientific computing. It reads almost like plain English, which is why universities and employers use it as the default entry point into programming. If you learn one language in 2026, make it Python.</p><h2>What you will actually learn</h2><p>A solid fundamentals course takes you from zero to writing real, useful programs:</p><ul><li>Variables, data types, lists and dictionaries</li><li>Conditionals and loops to control program flow</li><li>Functions and modules to organise reusable code</li><li>Reading and writing files, and handling errors gracefully</li><li>Using libraries to do heavy lifting in a few lines</li></ul><h2>What you can build with Python</h2><table><tr><th>Goal</th><th>What Python does for you</th></tr><tr><td>Automate boring tasks</td><td>Rename files, scrape data, send reports on a schedule</td></tr><tr><td>Analyse data</td><td>Crunch spreadsheets and CSVs with pandas</td></tr><tr><td>Enter AI and machine learning</td><td>Python is the language of TensorFlow, PyTorch and scikit-learn</td></tr><tr><td>Build web apps and APIs</td><td>Flask and Django power real products</td></tr></table><p>In our hands-on class you write and run Python from your first hour, building small programs that solve real problems. The <a href="{{store direct_url=''wsq-python-fundamental-course-for-beginners.html''}}">WSQ Python Fundamental Course for Beginners</a> is designed for people with no coding background.</p><h2>Who should learn Python?</h2><ul><li>Complete beginners who want a future-proof, high-demand skill</li><li>Analysts and ops staff who want to automate repetitive work</li><li>Anyone planning to move into data science or AI later</li><li>Professionals switching careers into tech</li></ul><h2>Fund your upskilling: WSQ funding + SkillsFuture Credit</h2><p>This is a <strong>WSQ-accredited course</strong>, so eligible Singaporeans and PRs get <strong>up to 70% WSQ course-fee funding</strong>, and Singaporeans can <strong>claim SkillsFuture Credit</strong> to offset the remaining fee. Employers sponsoring staff enjoy the same subsidies plus absentee payroll support, and SMEs get enhanced rates. <a href="{{store direct_url=''wsq-python-fundamental-course-for-beginners.html''}}">Check funding and upcoming dates here</a>.</p><h2>FAQ</h2><h3>Do I need any coding experience?</h3><p>None at all. The course starts from absolute basics and builds up step by step with a trainer guiding every exercise.</p><h3>Can I use SkillsFuture Credit for this course?</h3><p>Yes. As a WSQ course it is SkillsFuture-eligible — the WSQ subsidy applies first, then your SkillsFuture Credit covers the nett fee.</p><h3>What can I do after this course?</h3><p>You can automate tasks at work, then progress to data analytics, machine learning or web development. Python is the on-ramp to all of them.</p><h2>What to do next</h2><ol><li>Think of one repetitive task you would love to automate</li><li>Reserve a seat in the <a href="{{store direct_url=''wsq-python-fundamental-course-for-beginners.html''}}"><strong>WSQ Python Fundamental Course for Beginners</strong></a> — funded places go fast</li><li>Bring your laptop and leave writing working Python code</li></ol>', 'Tertiary Infotech Academy', 1, '2026-06-19', 'TGS-2019503161', 'TGS-2019503161', 'Python Course for Beginners Singapore | WSQ Funded Training', 'Learn Python from scratch — what you can build and how to master it with up to 70% WSQ funding and SkillsFuture Credit in Singapore.', 'python course, learn python, programming for beginners, wsq funding, skillsfuture, python singapore', NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `mmd_blog_post` WHERE `url_key` = 'python-fundamentals-for-beginners');

