-- 4) Creating Engaging Videos with GenAI — TGS-2024043855
-- =====================================================================
INSERT INTO `mmd_blog_post` (`title`, `url_key`, `excerpt`, `content`, `author`, `status`, `published_at`, `related_skus`, `source_sku`, `meta_title`, `meta_description`, `meta_keywords`, `created_at`, `updated_at`) SELECT 'Create Engaging Videos with Generative AI in Minutes, Not Days', 'create-engaging-videos-with-generative-ai', 'Generative AI turns a script or idea into a polished video without a film crew. Here is how it works and how to master it with up to 70% WSQ funding and SkillsFuture Credit.', '<h2>Video is the format that wins attention — and AI just made it easy</h2><p>Short-form video drives the most engagement across social media, marketing and training, but traditional production is slow and expensive. Generative AI changes that: you can now turn a script, a set of images or even a text prompt into a finished, professional-looking video in minutes.</p><h2>What you will learn</h2><p>A practical GenAI video course covers the full modern toolkit:</p><ul><li>Turning ideas and scripts into storyboards and shot lists with AI</li><li>Generating video clips, voiceovers and AI presenters from text</li><li>Auto-captioning, background music and B-roll</li><li>Editing and polishing AI-generated footage into a coherent story</li><li>Producing content sized for TikTok, Instagram Reels, YouTube and LinkedIn</li></ul><h2>What you can create</h2><table><tr><th>Use case</th><th>What GenAI produces</th></tr><tr><td>Marketing and ads</td><td>Product promos and social clips at a fraction of the cost</td></tr><tr><td>Training and explainers</td><td>Talking-head lessons without a studio or camera</td></tr><tr><td>Personal brand</td><td>Consistent short-form content that keeps you visible</td></tr><tr><td>Corporate comms</td><td>Announcements and internal updates in minutes</td></tr></table><p>In our hands-on class you produce a complete AI-generated video from a simple brief. The <a href="{{store direct_url=''wsq-creating-engaging-videos-with-generative-ai-genai.html''}}">WSQ Creating Engaging Videos with Generative AI course</a> is built for marketers and creators, not video engineers.</p><h2>Who should learn this?</h2><ul><li>Marketers and social media managers who need volume without a big budget</li><li>Business owners and solopreneurs building a personal brand</li><li>Trainers and educators producing lesson content</li><li>Content creators who want to work faster</li></ul><h2>Fund your learning: WSQ funding + SkillsFuture Credit</h2><p>This is a <strong>WSQ-accredited course</strong>, so eligible Singaporeans and PRs get <strong>up to 70% WSQ course-fee funding</strong>, and Singaporeans can <strong>use SkillsFuture Credit</strong> to offset the balance. Companies sponsoring staff enjoy the same subsidies plus absentee payroll support. <a href="{{store direct_url=''wsq-creating-engaging-videos-with-generative-ai-genai.html''}}">Check funding and class dates here</a>.</p><h2>FAQ</h2><h3>Do I need video editing experience?</h3><p>No. The course teaches AI-first workflows where the tools do the heavy lifting — you focus on the message and the story.</p><h3>Can I use SkillsFuture Credit for this course?</h3><p>Yes. As a WSQ course it is SkillsFuture-eligible — apply the WSQ subsidy first, then use SkillsFuture Credit for the nett fee.</p><h3>Which AI video tools are covered?</h3><p>You will work with current generative video, voice and editing tools, and learn a workflow that adapts as the tools evolve.</p><h2>What to do next</h2><ol><li>Pick one video you have been meaning to make — an ad, an explainer, an intro</li><li>Reserve a seat in the <a href="{{store direct_url=''wsq-creating-engaging-videos-with-generative-ai-genai.html''}}"><strong>WSQ Creating Engaging Videos with Generative AI</strong></a> class</li><li>Leave with a finished video and a repeatable production workflow</li></ol>', 'Tertiary Infotech Academy', 1, '2026-06-24', 'TGS-2024043855', 'TGS-2024043855', 'Create Videos with Generative AI Course Singapore | WSQ Funded', 'Learn to make engaging videos with generative AI — no film crew needed. WSQ course in Singapore with up to 70% funding and SkillsFuture Credit.', 'generative ai video, ai video creation, genai course, content marketing, wsq funding, skillsfuture', NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `mmd_blog_post` WHERE `url_key` = 'create-engaging-videos-with-generative-ai');

