-- 6) PMP 35 PDU — TGS-2024045797
-- =====================================================================
INSERT INTO `mmd_blog_post` (`title`, `url_key`, `excerpt`, `content`, `author`, `status`, `published_at`, `related_skus`, `source_sku`, `meta_title`, `meta_description`, `meta_keywords`, `created_at`, `updated_at`) SELECT 'PMP Certification Explained: The 35 Contact Hours You Need to Qualify', 'pmp-certification-35-pdu-guide', 'The PMP is the gold-standard project management certification, and you need 35 contact hours to sit the exam. Here is how it works and how to get there with up to 70% WSQ funding and SkillsFuture Credit.', '<h2>Why the PMP is still the most respected project management credential</h2><p>The Project Management Professional (PMP) certification from the Project Management Institute (PMI) is recognised worldwide and consistently linked to higher salaries and better roles. Whatever your industry, PMP signals that you can lead projects predictably from initiation to close.</p><h2>The 35 contact hours requirement</h2><p>Before you can sit the PMP exam, PMI requires <strong>35 contact hours (PDUs) of formal project management education</strong>. A structured 35-PDU training course fulfils this prerequisite and prepares you for the exam at the same time. You will cover:</p><ul><li>The PMI framework: people, process and business environment</li><li>Predictive, agile and hybrid delivery approaches</li><li>Managing scope, schedule, cost, quality and risk</li><li>Leading teams, stakeholders and communications</li><li>Exam strategy and practice questions</li></ul><h2>What PMP does for your career</h2><table><tr><th>Benefit</th><th>What it means for you</th></tr><tr><td>Global recognition</td><td>A credential respected across industries and countries</td></tr><tr><td>Higher earning potential</td><td>PMP holders consistently report a salary premium</td></tr><tr><td>Career mobility</td><td>Qualifies you for senior project and programme roles</td></tr><tr><td>A common language</td><td>Proven frameworks your whole team can align on</td></tr></table><p>Our instructor-led class delivers all 35 contact hours and drills the exam content. The <a href="{{store direct_url=''wsq-project-management-professional-pmp-35-pdu-training.html''}}">WSQ Project Management Professional (PMP) 35 PDU Training course</a> gives you both the prerequisite and the preparation.</p><h2>Who should take this?</h2><ul><li>Project managers ready to formalise their experience with a credential</li><li>Team leads and coordinators moving into project roles</li><li>Professionals who manage projects without the title — yet</li><li>Anyone targeting senior delivery and programme positions</li></ul><h2>Fund your certification: WSQ funding + SkillsFuture Credit</h2><p>This is a <strong>WSQ-accredited course</strong>, so eligible Singaporeans and PRs get <strong>up to 70% WSQ course-fee funding</strong>, and Singaporeans can <strong>use SkillsFuture Credit</strong> to offset the balance. Company-sponsored candidates enjoy the same subsidies plus absentee payroll support. <a href="{{store direct_url=''wsq-project-management-professional-pmp-35-pdu-training.html''}}">Check funding and class dates here</a>.</p><h2>FAQ</h2><h3>Does this course qualify me to sit the PMP exam?</h3><p>Yes. It delivers the 35 contact hours of project management education that PMI requires as a prerequisite, in addition to preparing you for the exam.</p><h3>Can I use SkillsFuture Credit?</h3><p>Yes. As a WSQ course it is SkillsFuture-eligible — apply the WSQ subsidy first, then use your SkillsFuture Credit for the nett fee.</p><h3>Do I need project management experience?</h3><p>PMI has its own experience eligibility for the exam. The course itself welcomes anyone building toward the certification, and our trainers advise you on eligibility.</p><h2>What to do next</h2><ol><li>Confirm your PMP eligibility — our team can walk you through the PMI requirements</li><li>Reserve a seat in the <a href="{{store direct_url=''wsq-project-management-professional-pmp-35-pdu-training.html''}}"><strong>WSQ PMP 35 PDU Training</strong></a> class</li><li>Earn your 35 contact hours and walk in exam-ready</li></ol>', 'Tertiary Infotech Academy', 1, '2026-06-28', 'TGS-2024045797', 'TGS-2024045797', 'PMP Certification 35 PDU Training Singapore | WSQ Funded', 'Get the 35 contact hours you need for the PMP exam. WSQ project management course in Singapore with up to 70% funding and SkillsFuture Credit.', 'pmp certification, project management, 35 pdu, pmi, wsq funding, skillsfuture, pmp singapore', NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `mmd_blog_post` WHERE `url_key` = 'pmp-certification-35-pdu-guide');

-- =====================================================================
-- 7) Agentic AI Automation with n8n — TGS-2023035977
-- =====================================================================
INSERT INTO `mmd_blog_post` (`title`, `url_key`, `excerpt`, `content`, `author`, `status`, `published_at`, `related_skus`, `source_sku`, `meta_title`, `meta_description`, `meta_keywords`, `created_at`, `updated_at`) SELECT 'Agentic AI Automation with n8n: Build Workflows That Think and Act', 'agentic-ai-automation-with-n8n', 'n8n lets you build AI agents that connect your apps and automate real work — visually. Here is what you can build and how to master it with up to 70% WSQ funding and SkillsFuture Credit.', '<h2>Automation grew up — now your workflows can reason</h2><p>Classic automation follows fixed rules. Agentic AI automation adds a brain: workflows that call a large language model, make decisions, use tools and adapt to context. <strong>n8n</strong> is the open, visual platform that makes this practical — you wire together apps, data and AI on a canvas instead of writing thousands of lines of code.</p><h2>What you will learn</h2><p>A hands-on n8n course takes you from your first workflow to full AI agents:</p><ul><li>Building visual workflows that connect hundreds of apps and APIs</li><li>Triggers, nodes and data mapping to move information between systems</li><li>Adding LLM nodes so workflows can summarise, classify and decide</li><li>Designing AI agents that call tools and take multi-step actions</li><li>Deploying, scheduling and monitoring your automations</li></ul><h2>What you can build</h2><table><tr><th>Use case</th><th>What n8n automates</th></tr><tr><td>Lead and CRM ops</td><td>Capture, enrich and route leads automatically</td></tr><tr><td>Content pipelines</td><td>Generate, review and publish content on a schedule</td></tr><tr><td>Support triage</td><td>Read incoming messages, classify and draft replies</td></tr><tr><td>Data sync</td><td>Keep systems in sync without manual copy-paste</td></tr></table><p>In our hands-on class you build working agentic workflows from real business scenarios. The <a href="{{store direct_url=''wsq-agentic-ai-automation-with-n8n.html''}}">WSQ Agentic AI Automation with n8n course</a> suits both non-coders and technical users.</p><h2>Who should learn this?</h2><ul><li>Operations and marketing teams automating repetitive processes</li><li>Founders and solopreneurs who want to do more without more headcount</li><li>Analysts and IT staff building internal automation</li><li>Anyone moving into the fast-growing AI automation field</li></ul><h2>Fund your upskilling: WSQ funding + SkillsFuture Credit</h2><p>This is a <strong>WSQ-accredited course</strong>, so eligible Singaporeans and PRs get <strong>up to 70% WSQ course-fee funding</strong>, and Singaporeans can <strong>use SkillsFuture Credit</strong> to offset the balance. Employers sponsoring staff enjoy the same subsidies plus absentee payroll support. <a href="{{store direct_url=''wsq-agentic-ai-automation-with-n8n.html''}}">Check funding and class dates here</a>.</p><h2>FAQ</h2><h3>Do I need to be a programmer?</h3><p>No. n8n is visual and low-code. Some workflows use small snippets, but the course teaches you everything you need from scratch.</p><h3>Can I claim SkillsFuture Credit?</h3><p>Yes. As a WSQ course it is SkillsFuture-eligible — the WSQ subsidy applies first, then SkillsFuture Credit covers the nett fee.</p><h3>How is n8n different from Zapier or Make?</h3><p>n8n is open, self-hostable and far more flexible for complex, AI-driven workflows — which is exactly what agentic automation needs.</p><h2>What to do next</h2><ol><li>Pick one multi-step process you repeat every week</li><li>Reserve a seat in the <a href="{{store direct_url=''wsq-agentic-ai-automation-with-n8n.html''}}"><strong>WSQ Agentic AI Automation with n8n</strong></a> class</li><li>Leave with working AI agents automating that process for you</li></ol>', 'Tertiary Infotech Academy', 1, '2026-06-30', 'TGS-2023035977', 'TGS-2023035977', 'Agentic AI Automation with n8n Course Singapore | WSQ Funded', 'Learn to build AI agents and automations with n8n. WSQ course in Singapore with up to 70% funding and SkillsFuture Credit.', 'n8n, agentic ai, ai automation, workflow automation, wsq funding, skillsfuture, no code ai', NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `mmd_blog_post` WHERE `url_key` = 'agentic-ai-automation-with-n8n');

